update public.character_art_assets a set
  bundle_path = v.bundle_path, sha256 = v.sha256, alt_text = v.alt_text,
  is_placeholder = true,  -- interim flat art until final 3D art is commissioned
  license_status = 'ai_generated_assigned',
  attribution = 'Drawn with Claude Design (Anthropic) for GeoMaster',
  provenance = 'ai_generated:claude_design; interim flat vector art from the GeoMaster design canvas; owner confirmed 2026-11-16; final 3D art to keep the same file names',
  cultural_review_status = case when p.slug in ('al_biruni', 'hypatia_of_alexandria', 'ibn_battuta', 'zheng_he')
                                then 'pending' else 'not_required' end
from (values
  ('rank_legend', 'tourist', 'assets/art/characters/rank-legends/rank-1-tourist-marco-polo.svg', 'b891046dacc03fc705052c1f7aec361eaebd1c820468df25713ddefc1a66da30', 'Marco Polo'),
