  and a.character_role_id = c.id and a.variant = 'bust';

-- characters/locked-legend-silhouette.svg and trophies/locked.svg are generic UI art (bundled, not per person).

update public.trophy_definitions t set art_bundle_dir = v.dir
from (values
  ('travelers_compass', 'assets/art/trophies/travelers-compass'),
  ('golden_travel_journal', 'assets/art/trophies/golden-travel-journal'),
  ('treasure_fleet_ship', 'assets/art/trophies/treasure-fleet-ship'),
  ('ocean_astrolabe', 'assets/art/trophies/ocean-astrolabe'),
  ('golden_world_atlas', 'assets/art/trophies/golden-world-atlas--golden-atlas'),
  ('earths_ecosystem_globe', 'assets/art/trophies/earths-ecosystem-globe'),
  ('celestial_globe', 'assets/art/trophies/celestial-globe'),
  ('golden_earth_sphere', 'assets/art/trophies/golden-earth-sphere'),
  ('crown_of_knowledge', 'assets/art/trophies/crown-of-knowledge'),
  ('golden_atlas', 'assets/art/trophies/golden-world-atlas--golden-atlas'),
  ('scroll_of_ages', 'assets/art/trophies/scroll-of-ages'),
  ('golden_balance', 'assets/art/trophies/golden-balance'),
  ('pillars_of_wisdom', 'assets/art/trophies/pillars-of-wisdom'),
  ('celestial_telescope', 'assets/art/trophies/celestial-telescope'),
  ('orb_of_knowledge', 'assets/art/trophies/orb-of-knowledge'),
